          acceptedResponses += 1;
          if (acceptedResponses > CAPS.maximumAcceptedResponses) {
            return reject(new Error('accepted-response cap exceeded'));
          }
          if (aggregateBytes > CAPS.maximumAggregateWireBytes) {
            return reject(new Error('aggregate wire byte cap exceeded'));
          }
          resolve({ body, sha256, status: res.statusCode, headers: res.headers });
        });
      }
    );
    req.on('error', reject);
    req.end();
  });
}

function gitBlobSha(buf) {
  const h = crypto.createHash('sha1');
  h.update(Buffer.from(`blob ${buf.length}\0`, 'utf8'));
  h.update(buf);
  return h.digest('hex');
}

function sha256(buf) {
  return crypto.createHash('sha256').update(buf).digest('hex');
}

function walk(dir, base, out) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const abs = path.join(dir, e.name);
    const rel = base ? base + '/' + e.name : e.name;
    if (e.isSymbolicLink()) out.push({ rel, kind: 'symlink' });
    else if (e.isDirectory()) {
      out.push({ rel, kind: 'dir' });
      walk(abs, rel, out);
    } else if (e.isFile()) out.push({ rel, kind: 'file', abs });
    else out.push({ rel, kind: 'special' });
  }
  return out;
}

async function main() {
  gate();
  fs.mkdirSync(EVIDENCE, { recursive: true });
  fs.mkdirSync(ARCHIVE_DIR, { recursive: true });
  fs.mkdirSync(VERIFY_DIR, { recursive: true });

  const facts = { unit: UNIT, slug: SLUG, consentId: CONSENT_ID, startedAt: new Date().toISOString() };

  // ---- step 1: repository metadata
  note(1, 'repository metadata', `https://api.github.com/repos/${REPO}`);
  const meta = await get(`https://api.github.com/repos/${REPO}`);
  const metaJson = JSON.parse(meta.body.toString('utf8'));
  facts.repository = {
    id: metaJson.id,
    fullName: metaJson.full_name,
    private: metaJson.private,
    archived: metaJson.archived,
    disabled: metaJson.disabled,
    fork: metaJson.fork,
    defaultBranch: metaJson.default_branch,
    createdAt: metaJson.created_at,
    pushedAt: metaJson.pushed_at,
    description: metaJson.description,
    homepage: metaJson.homepage,
    license: metaJson.license ? { key: metaJson.license.key, spdx: metaJson.license.spdx_id, name: metaJson.license.name } : null,
    responseBytes: meta.body.length,
    responseSha256: meta.sha256,
  };

  // ---- step 2: the tag ref
  note(2, 'tag ref', `https://api.github.com/repos/${REPO}/git/ref/tags/${TAG}`);
  const ref = await get(`https://api.github.com/repos/${REPO}/git/ref/tags/${TAG}`);
  const refJson = JSON.parse(ref.body.toString('utf8'));
  facts.tag = {
    ref: refJson.ref,
    objectType: refJson.object.type,
    objectSha: refJson.object.sha,
    responseBytes: ref.body.length,
    responseSha256: ref.sha256,
  };
  let commitSha = refJson.object.sha;
  if (refJson.object.type === 'tag') {
    note(2.5, 'annotated tag object dereference', refJson.object.sha);
    const tagObj = await get(`https://api.github.com/repos/${REPO}/git/tags/${refJson.object.sha}`);
    const tagJson = JSON.parse(tagObj.body.toString('utf8'));
    commitSha = tagJson.object.sha;
    facts.tag.annotated = true;
    facts.tag.tagger = tagJson.tagger ? { date: tagJson.tagger.date } : null;
    facts.tag.dereferencedCommitSha = commitSha;
    facts.tag.dereferenceResponseBytes = tagObj.body.length;
    facts.tag.dereferenceResponseSha256 = tagObj.sha256;
  } else {
    facts.tag.annotated = false;
  }
  facts.tag.expectedCommitSha = EXPECTED_SHA;
  facts.tag.expectedCommitShaConfirmedFromWire = commitSha === EXPECTED_SHA;
  if (commitSha !== EXPECTED_SHA) {
    throw new Error(`tag ${TAG} resolves to ${commitSha}, not the expected ${EXPECTED_SHA}`);
  }

  // ---- step 3: the commit object
  note(3, 'pinned commit object', commitSha);
  const commit = await get(`https://api.github.com/repos/${REPO}/commits/${commitSha}`);
  const commitJson = JSON.parse(commit.body.toString('utf8'));
  facts.revision = {
    ref: `refs/tags/${TAG}`,
    commitSha: commitJson.sha,
    committerDate: commitJson.commit.committer.date,
    authorDate: commitJson.commit.author.date,
    commitSubject: commitJson.commit.message.split('\n')[0],
    commitVerification: commitJson.commit.verification
      ? { verified: commitJson.commit.verification.verified, reason: commitJson.commit.verification.reason }
      : null,
    rootTreeSha: commitJson.commit.tree.sha,
    parents: commitJson.parents.map((p) => p.sha),
    responseBytes: commit.body.length,
    responseSha256: commit.sha256,
  };

  // ---- step 4: the recursive tree
  const treeSha = commitJson.commit.tree.sha;
  note(4, 'recursive git tree', treeSha);
  const tree = await get(`https://api.github.com/repos/${REPO}/git/trees/${treeSha}?recursive=1`);
  fs.writeFileSync(path.join(EVIDENCE, 'probe-tree.json'), tree.body);
  const treeJson = JSON.parse(tree.body.toString('utf8'));
  const blobs = treeJson.tree.filter((e) => e.type === 'blob');
  const dirs = treeJson.tree.filter((e) => e.type === 'tree');
  const commits = treeJson.tree.filter((e) => e.type === 'commit');
  const symlinks = blobs.filter((e) => e.mode === '120000');
  const execs = blobs.filter((e) => e.mode === '100755');
  facts.tree = {
    sha: treeSha,
    truncated: treeJson.truncated,
    entries: treeJson.tree.length,
    blobs: blobs.length,
    directories: dirs.length,
    gitlinks: commits.length,
    symlinks: symlinks.length,
    executableBlobs: execs.length,
    blobBytes: blobs.reduce((a, b) => a + (b.size || 0), 0),
    responseBytes: tree.body.length,
    responseSha256: tree.sha256,
  };
  if (treeJson.truncated) throw new Error('recursive tree response was truncated — cannot reconcile');

  // ---- step 5: the archive, twice
  const archiveUrl = `https://codeload.github.com/${REPO}/tar.gz/${commitSha}`;
  const digests = [];
  for (const stream of [1, 2]) {
    note(5, `source archive stream ${stream}`, archiveUrl);
    const arc = await get(archiveUrl, { stream, accept: 'application/x-gzip' });
    if (arc.body.length > CAPS.maximumArchiveBytes) throw new Error('archive byte cap exceeded');
    fs.writeFileSync(path.join(ARCHIVE_DIR, `archive-${stream}.tar.gz`), arc.body);
    digests.push({ stream, bytes: arc.body.length, sha256: arc.sha256 });
  }
  const byteIdentical = digests[0].sha256 === digests[1].sha256 && digests[0].bytes === digests[1].bytes;
  if (!byteIdentical) throw new Error('the two archive fetches are not byte-identical');
  facts.archive = { url: archiveUrl, bytes: digests[0].bytes, sha256: digests[0].sha256, streams: 2, byteIdentical: true };

  // ---- step 6: offline reconciliation
  note(6, 'offline reconciliation', 'extract archive and hash every regular file as a git blob');
  fs.rmSync(VERIFY_DIR, { recursive: true, force: true });
  fs.mkdirSync(VERIFY_DIR, { recursive: true });
  execFileSync('tar', ['-xzf', path.join(ARCHIVE_DIR, 'archive-1.tar.gz'), '-C', VERIFY_DIR]);
  const roots = fs.readdirSync(VERIFY_DIR);
  if (roots.length !== 1) throw new Error(`archive does not have a single root: ${roots.join(',')}`);
  const singleRoot = roots[0];
  const srcRoot = path.join(VERIFY_DIR, singleRoot);
  const entries = walk(srcRoot, '', []);
  const files = entries.filter((e) => e.kind === 'file');
  const treeMap = new Map(blobs.map((b) => [b.path, b]));
  const seen = new Set();
  const mismatched = [];
  const extra = [];
  const manifest = [];
  for (const f of files) {
    const buf = fs.readFileSync(f.abs);
    const blobSha = gitBlobSha(buf);
    const t = treeMap.get(f.rel);
    if (!t) extra.push(f.rel);
    else {
      seen.add(f.rel);
      if (t.sha !== blobSha) mismatched.push({ path: f.rel, tree: t.sha, archive: blobSha });
    }
    manifest.push(`${f.rel} ${blobSha} ${buf.length}`);
  }
  const missing = blobs.filter((b) => !seen.has(b.path)).map((b) => b.path);
  manifest.sort();
  const normalizedManifestSha256 = sha256(Buffer.from(manifest.join('\n') + '\n', 'utf8'));
  const traversal = entries.filter((e) => e.rel.split('/').includes('..'));
  facts.reconciliation = {
    singleRoot,
    archiveEntries: entries.length + 1,
    regularFiles: files.length,
    directories: entries.filter((e) => e.kind === 'dir').length + 1,
    symlinkEntries: entries.filter((e) => e.kind === 'symlink').length,
    specialEntries: entries.filter((e) => e.kind === 'special').length,
    gitBlobs: blobs.length,
    missingFiles: missing.length,
    missingPaths: missing.slice(0, 20),
    extraFiles: extra.length,
    extraPaths: extra.slice(0, 20),
    mismatchedBlobs: mismatched.length,
    mismatchedDetail: mismatched.slice(0, 20),
    pathTraversalEntries: traversal.length,
    absolutePathEntries: entries.filter((e) => e.rel.startsWith('/')).length,
    normalizedManifestSha256,
  };

  // ---- key files, read out of the reconciled archive
  const keyPaths = [
    'LICENSE', 'LICENSE.md', 'license', 'COPYING', 'NOTICE',
    'package.json', 'package-lock.json', 'yarn.lock', 'npm-shrinkwrap.json',
    'angular.json', 'tsconfig.json', 'ngsw-config.json', '.gitattributes', '.nvmrc',
    'src/assets/data/data.json', 'README.md',
  ];
  facts.keyFiles = {};
  for (const p of keyPaths) {
    const abs = path.join(srcRoot, p);
    if (!fs.existsSync(abs) || !fs.statSync(abs).isFile()) {
      facts.keyFiles[p] = { present: false };
      continue;
    }
    const buf = fs.readFileSync(abs);
    facts.keyFiles[p] = {
      present: true,
      bytes: buf.length,
      sha256: sha256(buf),
      gitBlobSha: gitBlobSha(buf),
    };
  }

  // ---- Git LFS check: .gitattributes routing + pointer-stub scan
  const lfsAttr = [];
  const gaPath = path.join(srcRoot, '.gitattributes');
  if (fs.existsSync(gaPath)) {
    for (const line of fs.readFileSync(gaPath, 'utf8').split('\n')) {
      if (/filter=lfs/.test(line)) lfsAttr.push(line.trim());
    }
  }
  const pointers = [];
  for (const f of files) {
    const st = fs.statSync(f.abs);
    if (st.size > 400) continue;
    const head = fs.readFileSync(f.abs, 'utf8').slice(0, 200);
    if (head.startsWith('version https://git-lfs.github.com/spec/')) {
      const oid = /oid sha256:([0-9a-f]{64})/.exec(head);
      const size = /size (\d+)/.exec(head);
      pointers.push({ path: f.rel, oid: oid && oid[1], size: size && Number(size[1]) });
    }
  }
  facts.gitLargeFileStorage = {
    gitattributesPresent: fs.existsSync(gaPath),
    lfsFilterLines: lfsAttr,
    pointerFilesInArchive: pointers.length,
    pointers,
  };

  // ---- application shape inventory (offline, from the reconciled tree)
  const byExt = {};
  for (const b of blobs) {
    const ext = path.extname(b.path).toLowerCase() || '(none)';
    byExt[ext] = (byExt[ext] || 0) + 1;
  }
  facts.shape = {
    blobsByExtension: byExt,
    topLevelEntries: fs.readdirSync(srcRoot).sort(),
    srcAppEntries: fs.existsSync(path.join(srcRoot, 'src', 'app'))
      ? fs.readdirSync(path.join(srcRoot, 'src', 'app')).sort()
      : null,
    pagesEntries: fs.existsSync(path.join(srcRoot, 'src', 'app', 'pages'))
      ? fs.readdirSync(path.join(srcRoot, 'src', 'app', 'pages')).sort()
      : null,
  };

  facts.transaction = {
    ledgeredRequests: ledger.length,
    acceptedResponses,
    aggregateWireBytes: aggregateBytes,
    nonTwoHundredResponses: ledger.filter((r) => r.status !== 200).length,
    redirectsFollowed: 0,
    credentialsSent: 0,
    retries: 0,
  };
  facts.completedAt = new Date().toISOString();
  facts.cache = { root: path.relative(ROOT, CACHE), extracted: path.relative(ROOT, srcRoot) };

  fs.writeFileSync(path.join(EVIDENCE, 'probe-ledger.ndjson'), ledger.map((r) => JSON.stringify(r)).join('\n') + '\n');
  fs.writeFileSync(path.join(EVIDENCE, 'transcript.ndjson'), transcript.map((r) => JSON.stringify(r)).join('\n') + '\n');
  fs.writeFileSync(path.join(CACHE, 'raw-facts.json'), JSON.stringify(facts, null, 2));
  process.stdout.write(JSON.stringify(facts, null, 2) + '\n');
}

main().catch((err) => {
  try {
    fs.mkdirSync(EVIDENCE, { recursive: true });
    fs.writeFileSync(path.join(EVIDENCE, 'probe-ledger.ndjson'), ledger.map((r) => JSON.stringify(r)).join('\n') + '\n');
    fs.writeFileSync(
      path.join(EVIDENCE, 'transcript.ndjson'),
      transcript.concat([{ at: new Date().toISOString(), step: 'abort', what: 'failure', detail: String(err.message) }])
        .map((r) => JSON.stringify(r))
        .join('\n') + '\n'
    );
  } catch (_) {}
  process.stderr.write('FAILED: ' + err.stack + '\n');
  process.exit(1);
});

